  void Add(Type type,int depth){if(depth>32||values.Count>16384)throw new NotSupportedException("Compiled initial type graph bound");if(type.IsPointer||type.IsByRef||type.ContainsGenericParameters||typeof(Delegate).IsAssignableFrom(type))return;string name=ExactInitialValueCodec.Canonical(type.FullName);if(values.TryGetValue(name,out var prior)&&prior!=type)throw new InvalidOperationException("Ambiguous compiled source type");values[name]=type;if(!type.IsArray&&type!=typeof(void)){var array=type.MakeArrayType();values[ExactInitialValueCodec.Canonical(array.FullName)]=array;}if(!expanded.Add(type))return;if(type.HasElementType){Add(type.GetElementType(),depth+1);return;}if(type.IsGenericType)foreach(var argument in type.GetGenericArguments())Add(argument,depth+1);if(type.IsPrimitive||type.IsEnum||type==typeof(string)||type==typeof(object))return;string ns=type.Namespace??"";if(!(ns.StartsWith("Game.",StringComparison.Ordinal)||ns=="Unity.Mathematics"||ns=="Unity.Entities"||ns=="Unity.Collections"||ns=="Unity.Transforms"||ns=="UnityEngine"))return;foreach(var field in type.GetFields(BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).Where(f=>!f.IsStatic))Add(field.FieldType,depth+1);}
